def rrf_score(rank, k=60):
    return 1.0 / (k + rank)

def reciprocal_rank_fusion(rankings):
    scores = {}
    for ranking in rankings:
        for rank, doc_id in enumerate(ranking, start=1):
            scores[doc_id] = scores.get(doc_id, 0.0) + rrf_score(rank)
    return sorted(scores.items(), key=lambda x: x[1], reverse=True)

dense_results  = ["d3", "d1", "d5", "d2", "d4"]
lexical_results = ["d1", "d3", "d2", "d5", "d4"]

fused = reciprocal_rank_fusion([dense_results, lexical_results])
print("RRF fused ranking:")
for doc_id, score in fused:
    print(f"  {doc_id}: {round(score, 4)}")
